<template>
  <div class="flex-interval" style="height: 100%">
    <div class="tree">
      <DeviceTree @node-click="handleNodeClick" :driver_protocol="2" />
    </div>
    <div class="p-15" style="width: 68vw; overflow: auto">
      <div class="d-flex">
        <el-radio-group v-model="playType" size="small">
          <el-radio-button :label="1">单屏</el-radio-button>
          <el-radio-button :label="4">四分屏</el-radio-button>
          <el-radio-button :label="6">六分屏</el-radio-button>
        </el-radio-group>
        <el-button size="small" class="ml-10" @click="isFullscreen = true"
          >全屏</el-button
        >
      </div>
      <div
        class="screen-video"
        :class="{
          fullscreen: isFullscreen,
          single: playType == 1,
          four: playType == 4,
          six: playType == 6,
        }"
      >
        <div class="video-item" v-for="(item, index) in playType" :key="index">
          <VideoPlayer
            :index="index"
            v-if="playList[index]"
            :src="playList[index].src"
            @closeVideo="closeVideoItem"
          />
          <el-button
            class="video-btn fs-18 el-icon-error"
            size="small"
            type="text"
            v-if="playList[index]&&!isFullscreen"
            @click="closeVideoItem(index)"
          >
          </el-button>
        </div>
        <el-button
          type="primary"
          class="exit-fullscreen"
          @click="isFullscreen = false"
          size="small"
        >
          退出全屏
        </el-button>
      </div>
    </div>
  </div>
</template>

<script>
import { getUrl } from "@/assets/utils/config";
import DeviceTree from "@/components/deviceTree.vue";
import VideoPlayer from "@/components/videoPlayer.vue";
export default {
  components: {
    DeviceTree,
    VideoPlayer,
  },
  data() {
    return {
      playType: 1,
      isFullscreen: false,
      playList: [],
    };
  },

  mounted() {
    this.setStyle();
  },
  methods: {
    closeVideoItem(index) {
      if (this.playList[index]) {
        this.$api
          .get("/media/stopPlay", {
            params: { pro_id: this.playList[index].id },
          })
          .then(() => {
            this.$nextTick(() => {
              this.playList.splice(index, 1);
            });
          });
      }
    },
    handleNodeClick(data, node) {
      if (node.level == 2) {
        let isVideo = this.playList.find((item) => item.id == data.id);
        if (isVideo) {
          this.$message.warning("请勿重复添加");
          return;
        }
        if (this.playList.length >= this.playType) {
          this.$message.warning("视频添加已到最大限制");
          return;
        }
        let url =
          data.protocol_config.is_preview_analysis == 1
            ? "/media/playAnalysis"
            : "/media/play";
        this.$api.get(url, { params: { pro_id: data.id } }).then((res) => {
          if (res.data.data.play_url) {
            let videoUrl = getUrl(res.data.data.play_url);
            // let videoUrl = res.data.data.play_url.replace(
            //   "127.0.0.1",
            //   "192.168.0.11"
            // );
            this.playList.push({ src: videoUrl, id: data.id });
          }
        });
      }
    },
    setStyle() {
      const elMain = document.querySelector(".el-main");
      if (elMain) {
        elMain.style.padding = "0px";
        elMain.style.overflow = "hidden";
      }
    },
  },
  beforeDestroy() {
    const elMain = document.querySelector(".el-main");
    if (elMain) {
      elMain.style.padding = "20px";
      elMain.style.overflow = "auto";
    }
  },
};
</script>

<style lang="scss" scoped>
::v-deep .video-wrapper {
  // padding: 0 !important;
  padding-bottom: 0 !important;
  height: 100%;
}
::v-deep .player-wrapper {
  height: 100%;
}
.tree {
  width: 12vw;
  border-right: 5px solid #f4f4f4;
  height: 100%;
  padding: 15px;
}
.screen-video {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  height: calc(100vh - 200px);
  margin-top: 10px;
  .video-item {
    position: relative;
    width: 97%;
    height: 100%;
    color: #fff;
    background: #000;
    .video-btn {
      position: absolute;
      right: 10px;
      z-index: 9999;
      top: 0;
    }
  }
  &.four {
    .video-item {
      width: 49%;
      height: 50%;
      border-bottom: 1px solid rgba(#fff, 0.2);
      border-right: 1px solid rgba(#fff, 0.2);
      :nth-child(2n) {
        border-right: none;
      }
    }
  }
  &.six {
    .video-item {
      width: 33%;
      height: 50%;
      border-bottom: 1px solid rgba(#fff, 0.2);
      border-right: 1px solid rgba(#fff, 0.2);
      :nth-child(3n) {
        border-right: none;
      }
    }
  }
  &.fullscreen {
    position: fixed;
    width: 100vw;
    height: 100vh;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 1000; /* 确保覆盖其他元素 */
    margin: 0;
    background: #000; /* 添加背景色 */
    .exit-fullscreen {
      display: block;
      position: fixed;
      top: 10px;
      right: 10px;
      z-index: 1001;
    }
    &.four {
      .video-item {
        width: 49.9%;
        height: 50%;
        border-bottom: 1px solid rgba(#fff, 0.2);
        border-right: 1px solid rgba(#fff, 0.2);
        :nth-child(2n) {
          border-right: none;
        }
      }
    }
    &.six {
      .video-item {
        width: 33%;
        height: 50%;
        border-bottom: 1px solid rgba(#fff, 0.2);
        border-right: 1px solid rgba(#fff, 0.2);
        :nth-child(3n) {
          border-right: none;
        }
      }
    }
  }
  .exit-fullscreen {
    display: none;
    position: absolute;

    z-index: 12;
  }
}
</style>
